"""v0.138 Screens for PRODUCT / consumer apps (music, OTT, short video, social, chat, news, notes, fitness, games, rides,
food delivery marketplace, travel, jobs, property, payments ...). Same shape as taxonomy.SCREENS: label, hi, why, data,
6 designs, plus `core` = words a screen of this kind really shows (the relevance check uses them).
Merged into taxonomy.SCREENS at import; ids never clash with the business / pro screens.

Designs are generic patterns of the KIND of app, never any company's own layout, name, logo or colours."""
from __future__ import annotations

from typing import Any


def _s(label: str, hi: str, why: str, core: str, *variants: str) -> dict[str, Any]:
    assert len(variants) == 6, label
    return {"label": label, "hi": hi, "why": why, "data": [], "variants": list(variants), "product": True,
            "core": [w.strip() for w in core.split(",") if w.strip()]}


